// Halogen prefix lookup
QString halogenPrefix(int z) {
    switch (z) {
        case 9:  return "fluoro";
        case 17: return "chloro";
        case 35: return "bromo";
        case 53: return "iodo";
        default: return "";
    }
}

// Halogen suffix lookup
QString halogenSuffixWord(int z) {
    switch (z) {
        case 9:  return "fluoride";
        case 17: return "chloride";
        case 35: return "bromide";
        case 53: return "iodide";
        default: return "";
    }
}

// Structural check for an isocyanate/isothiocyanate nitrogen (N=C=O or
// N=C=S) singly bonded to `fromCarbon`, independent of any precomputed map
// so it works the same in every duplicated classification region.
bool isIsocyanateNitrogen(int nNode, int fromCarbon, const Graph &g) {
    const GraphNode &n = g.nodes[nNode];
    if (n.atomicNumber != 7 || n.totalH != 0 || n.neighbors.size() != 2) return false;
    for (size_t k = 0; k < n.neighbors.size(); ++k) {
        int nn = n.neighbors[k];
        if (nn == fromCarbon || n.bondOrders[k] != 2 || g.nodes[nn].atomicNumber != 6) continue;
        const GraphNode &isoC = g.nodes[nn];
        if (isoC.neighbors.size() != 2) continue;
        for (size_t m = 0; m < isoC.neighbors.size(); ++m) {
            int isoNei = isoC.neighbors[m];
            int isoZ = g.nodes[isoNei].atomicNumber;
            if ((isoZ == 8 || isoZ == 16) && isoC.bondOrders[m] == 2 && g.nodes[isoNei].neighbors.size() == 1) {
                return true;
            }
        }
    }
    return false;
}

// Structural check for a nitroso nitrogen (-N=O) singly bonded to `fromCarbon`
bool isNitrosoNitrogen(int nNode, int fromCarbon, const Graph &g) {
    const GraphNode &n = g.nodes[nNode];
    if (n.atomicNumber != 7 || n.totalH != 0 || n.neighbors.size() != 2) return false;
    for (size_t k = 0; k < n.neighbors.size(); ++k) {
        int nn = n.neighbors[k];
        if (nn == fromCarbon) continue;
        if (g.nodes[nn].atomicNumber == 8 && n.bondOrders[k] == 2 && g.nodes[nn].neighbors.size() == 1) {
            return true;
        }
    }
    return false;
}

// Structural check for an azide nitrogen (-N=N=N, terminal charges not checked)
// singly bonded to `fromNode`. Mirrors the carbonAzide pre-scan detection.
bool isAzideNitrogen(int nNode, int fromNode, const Graph &g) {
    const GraphNode &n = g.nodes[nNode];
    if (n.totalH != 0 || n.neighbors.size() != 2) return false;
    int midN = -1;
    for (size_t j = 0; j < n.neighbors.size(); ++j) {
        int nei = n.neighbors[j];
        if (nei != fromNode && g.nodes[nei].atomicNumber == 7 && n.bondOrders[j] == 2) {
            midN = nei;
        }
    }
    if (midN == -1 || g.nodes[midN].totalH != 0 || g.nodes[midN].neighbors.size() != 2) return false;
    const GraphNode &mNode = g.nodes[midN];
    int termN = -1;
    for (size_t k = 0; k < mNode.neighbors.size(); ++k) {
        int mNei = mNode.neighbors[k];
        if (mNei != nNode && g.nodes[mNei].atomicNumber == 7 && mNode.bondOrders[k] == 2) {
            termN = mNei;
        }
    }
    return termN != -1 && g.nodes[termN].neighbors.size() == 1 && g.nodes[termN].totalH == 0;
}

// Structural check for a nitro nitrogen (-NO2) singly bonded to `fromCarbon`
bool isNitroNitrogen(int nNode, int fromCarbon, const Graph &g) {
    const GraphNode &n = g.nodes[nNode];
    if (n.atomicNumber != 7 || n.totalH != 0 || n.neighbors.size() != 3) return false;
    int oxygenCount = 0;
    for (size_t k = 0; k < n.neighbors.size(); ++k) {
        int nn = n.neighbors[k];
        if (nn != fromCarbon && g.nodes[nn].atomicNumber == 8 && g.nodes[nn].neighbors.size() == 1) {
            oxygenCount++;
        }
    }
    return oxygenCount == 2;
}

// Structural check for an unsubstituted hydrazinyl nitrogen (-NH-NH2) singly bonded to `fromNode`
bool isHydrazinylNitrogen(int nNode, int fromNode, const Graph &g) {
    const GraphNode &n = g.nodes[nNode];
    if (n.atomicNumber != 7 || n.neighbors.size() != 2) return false;
    for (size_t k = 0; k < n.neighbors.size(); ++k) {
        int nn = n.neighbors[k];
        if (nn == fromNode) continue;
        const GraphNode &nNei = g.nodes[nn];
        if (nNei.atomicNumber == 7 && nNei.totalH == 2 && nNei.neighbors.size() == 1) {
            return true;
        }
    }
    return false;
}

// Structural check for an azo nitrogen (R-N=N-R') singly bonded to `fromCarbon`.
// Both R and R' must be attached via carbon atoms.
bool isAzoNitrogen(int nNode, int fromCarbon, const Graph &g) {
    const GraphNode &n = g.nodes[nNode];
    if (n.atomicNumber != 7 || n.totalH != 0 || n.neighbors.size() != 2) return false;
    for (size_t k = 0; k < n.neighbors.size(); ++k) {
        int nn = n.neighbors[k];
        if (nn == fromCarbon) continue;
        if (g.nodes[nn].atomicNumber == 7 && n.bondOrders[k] == 2) {
            const GraphNode &farN = g.nodes[nn];
            if (farN.totalH != 0 || farN.neighbors.size() != 2) return false;
            for (size_t m = 0; m < farN.neighbors.size(); ++m) {
                int farNei = farN.neighbors[m];
                if (farNei == nNode) continue;
                if (g.nodes[farNei].atomicNumber == 6 && farN.bondOrders[m] == 1) {
                    return true;
                }
            }
        }
    }
    return false;
}

// Returns true if this is an acyl cyanide (explicitly out of scope for pseudohalide naming)
bool isAcylCyanide(int i, const Graph &g) {
    const GraphNode &node = g.nodes[i];
    for (size_t j = 0; j < node.neighbors.size(); ++j) {
        int nei = node.neighbors[j];
        int nZ = g.nodes[nei].atomicNumber;
        int order = node.bondOrders[j];

        // Acyl cyanide: -C(=O)-C#N (nitrile carbon attached via a C-C bond,
        // with no other heavy-atom substituents on that nitrile carbon).
        if (nZ == 6 && order == 1) {
            const GraphNode &neiNode = g.nodes[nei];
            int tripleNCount = 0;
            int otherHeavyAtoms = 0;
            for (size_t k = 0; k < neiNode.neighbors.size(); ++k) {
                int nn = neiNode.neighbors[k];
                if (g.nodes[nn].atomicNumber == 7 && neiNode.bondOrders[k] == 3) {
                    tripleNCount++;
                } else if (nn != i && g.nodes[nn].atomicNumber > 1) {
                    otherHeavyAtoms++;
                }
            }
            if (tripleNCount == 1 && otherHeavyAtoms == 0) return true;
        }
    }
    return false;
}

// Safety guard for the carbamate-ester branch namer: nameBranchGraph has a
// real, pre-existing bug (confirmed live, unrelated to any carbamate-specific
// code -- reproduces on a plain, unrelated acid-substituted cyclohexyl branch
// with no carbamate involved at all) where a branch that itself contains
// another ester or carboxylic-acid-like C(=O)-O group gets silently
// misrendered as something chemically different (an ester rendered as a
// plain ether-alcohol; an acid rendered as a gem-diol) instead of being
// named correctly or failing cleanly. Reject rather than trust the branch
// name whenever this shape is present, so a real molecule (GABAPENTIN
// ENACARBIL, confirmed via the FDA-drug sweep) gets an honest rejection
// instead of a confidently wrong name.
bool branchContainsEmbeddedAcylOxy(const Graph &g, int startNode, int fromNode) {
    std::vector<int> stack = {startNode};
    std::vector<bool> visited(g.nodes.size(), false);
    visited[startNode] = true;
    if (fromNode >= 0 && fromNode < static_cast<int>(visited.size())) visited[fromNode] = true;
    while (!stack.empty()) {
        int cur = stack.back(); stack.pop_back();
        const GraphNode &node = g.nodes[cur];
        if (node.atomicNumber == 6) {
            bool hasDoubleO = false, hasSingleO = false;
            for (size_t j = 0; j < node.neighbors.size(); ++j) {
                int nei = node.neighbors[j];
                if (g.nodes[nei].atomicNumber == 8) {
                    if (node.bondOrders[j] == 2) hasDoubleO = true;
                    else if (node.bondOrders[j] == 1) hasSingleO = true;
                }
            }
            if (hasDoubleO && hasSingleO) return true;
        }
        for (int nei : node.neighbors) {
            if (nei >= 0 && nei < static_cast<int>(visited.size()) && !visited[nei] && g.nodes[nei].atomicNumber > 1) {
                visited[nei] = true;
                stack.push_back(nei);
            }
        }
    }
    return false;
}

bool isPeroxyCarboxylicAcid(int i, const Graph &g) {
    const GraphNode &node = g.nodes[i];
    for (size_t j = 0; j < node.neighbors.size(); ++j) {
        int nei = node.neighbors[j];
        if (g.nodes[nei].atomicNumber == 8 && node.bondOrders[j] == 1) {
            const GraphNode &oNode = g.nodes[nei];
            if (oNode.neighbors.size() == 2) {
                for (size_t k = 0; k < oNode.neighbors.size(); ++k) {
                    int oNei = oNode.neighbors[k];
                    if (oNei != i && g.nodes[oNei].atomicNumber == 8 && oNode.bondOrders[k] == 1) {
                        const GraphNode &peroxyONode = g.nodes[oNei];
                        if (peroxyONode.totalH >= 1 || peroxyONode.neighbors.size() == 1) {
                            return true;
                        }
                    }
                }
            }
        }
    }
    return false;
}

bool isPlainBenzeneRing(int mol, const Graph &g, const std::map<int, int> &indigoToGraphIdx, int alkylRoot, int sO) {
    if (alkylRoot < 0 || alkylRoot >= static_cast<int>(g.nodes.size())) return false;
    if (g.nodes[alkylRoot].atomicNumber != 6) return false;

    int sssrIter = indigoIterateSSSR(mol);
    if (sssrIter < 0) return false;

    bool found = false;
    int subMol = 0;
    while ((subMol = indigoNext(sssrIter)) != 0) {
        std::set<int> ringIndigoIndices;
        int ringAtomIter = indigoIterateAtoms(subMol);
        if (ringAtomIter >= 0) {
            int atomHandle = 0;
            while ((atomHandle = indigoNext(ringAtomIter)) != 0) {
                ringIndigoIndices.insert(indigoIndex(atomHandle));
                indigoFree(atomHandle);
            }
            indigoFree(ringAtomIter);
        }
        indigoFree(subMol);

        if (found) continue;

        if (ringIndigoIndices.size() == 6) {
            std::set<int> candidateRingNodes;
            std::vector<int> ringHeteroNodes;
            bool validNodes = true;
            for (int idx : ringIndigoIndices) {
                if (indigoToGraphIdx.count(idx)) {
                    int gIdx = indigoToGraphIdx.at(idx);
                    candidateRingNodes.insert(gIdx);
                    if (g.nodes[gIdx].atomicNumber != 6) {
                        ringHeteroNodes.push_back(gIdx);
                    }
                } else {
                    validNodes = false;
                }
            }

            if (validNodes && candidateRingNodes.size() == 6 && candidateRingNodes.count(alkylRoot) > 0) {
                if (ringHeteroNodes.empty()) {
                    bool allAromatic = true;
                    bool allSingle = true;
                    bool hasDouble = false;
                    bool hasTriple = false;

                    for (const auto &gb : g.bonds) {
                        if (candidateRingNodes.count(gb.u) && candidateRingNodes.count(gb.v)) {
                            if (gb.order != 4) allAromatic = false;
                            if (gb.order != 1) allSingle = false;
                            if (gb.order == 2) hasDouble = true;
                            if (gb.order == 3) hasTriple = true;
                        }
                    }

                    bool isBenzene = (!hasTriple) && (allAromatic || (!allSingle && !hasDouble));
                    if (isBenzene) {
                        int nodesWithExo = 0;
                        bool validSubstituent = true;

                        for (int rNode : candidateRingNodes) {
                            int exoCount = 0;
                            for (size_t j = 0; j < g.nodes[rNode].neighbors.size(); ++j) {
                                int nei = g.nodes[rNode].neighbors[j];
                                if (!candidateRingNodes.count(nei)) {
                                    exoCount++;
                                    if (rNode == alkylRoot && nei == sO && g.nodes[rNode].bondOrders[j] == 1) {
                                        // attached to oxygen of ester
                                    } else {
                                        validSubstituent = false;
                                    }
                                }
                            }
                            if (exoCount > 1) {
                                validSubstituent = false;
                            } else if (exoCount == 1) {
                                nodesWithExo++;
                            }
                        }

                        if (validSubstituent && nodesWithExo == 1) {
                            found = true;
                        }
                    }
                }
            }
        }
    }
    indigoFree(sssrIter);
    return found;
}

// Alphabetization key for substituent-citation sorting and numbering-tiebreak scoring.
// Strips wrapping brackets a substituent name may carry (from compound-substituent or
// stereo-prefix wrapping), then a leading stereo-descriptor parenthetical like "(1R)-", then
// a leading locant-digit(s)-hyphen sequence like "1-", down to the true alphabetic root --
// e.g. "[(1R)-1-chloroethyl]" -> "chloroethyl". Plain names like "bromo" pass through
// unchanged.
QString alphabetizationKey(const QString &pName) {
    QString s = pName;
    if ((s.startsWith("(") && s.endsWith(")")) || (s.startsWith("[") && s.endsWith("]"))) {
        s = s.mid(1, s.length() - 2);
    } else if (s.startsWith("(") || s.startsWith("[")) {
        s = s.mid(1);
    }
    if (s.startsWith("(")) {
        int closeParen = s.indexOf(')');
        if (closeParen != -1 && closeParen + 1 < s.length() && s[closeParen + 1] == '-') {
            s = s.mid(closeParen + 2);
        }
    }
    int i = 0;
    while (i < s.length() && (s[i].isDigit() || s[i] == ',')) i++;
    if (i > 0 && i < s.length() && s[i] == '-') {
        s = s.mid(i + 1);
    }
    return s;
}

// P-22.2.2.1.3 citation-order seniority rank for Hantzsch-Widman naming.
// Lower rank = more senior (gets locant 1 preference).
// Order: O > S > Se > Te > N > P > As > Sb > Bi > Si > Ge > Sn > Pb > B
// NOTE: This is NOT the same as getRankHetero used for fused-ring base-component
// seniority (P-25.3.2) -- that ranks N highest and is a completely different rule.
static int hwSeniorityRank(int z) {
    switch (z) {
        case  8: return  0; // O
        case 16: return  1; // S
        case 34: return  2; // Se
        case 52: return  3; // Te
        case  7: return  4; // N
        case 15: return  5; // P
        case 33: return  6; // As
        case 51: return  7; // Sb
        case 83: return  8; // Bi
        case 14: return  9; // Si
        case 32: return 10; // Ge
        case 50: return 11; // Sn
        case 82: return 12; // Pb
        case  5: return 13; // B
        default: return 99; // unsupported
    }
}

// Return the 'a'-replacement prefix for a supported heteroatom atomic number.
static QString hwAPrefix(int z) {
    switch (z) {
        case  8: return "oxa";
        case 16: return "thia";
        case 34: return "selena";
        case 52: return "tellura";
        case  7: return "aza";
        case 15: return "phospha";
        case 33: return "arsa";
        case 51: return "stiba";
        case 83: return "bisma";
        case 14: return "sila";
        case 32: return "germa";
        case 50: return "stanna";
        case 82: return "plumba";
        case  5: return "bora";
        default: return "";
    }
}

// P-44.2.1 criterion (c) and (g) heteroatom seniority ranks.
// Lower rank = occurs earlier in the Blue Book sequence = more senior.
// Criterion (c): F > Cl > Br > I > O > S > Se > Te > P > As > Sb > Bi > Si > Ge > Sn > Pb > B > Al > Ga > In > Tl
//   (used when comparing heteroatoms "in the absence of nitrogen")
// Criterion (g): F > Cl > Br > I > O > S > Se > Te > N > P > As > Sb > Bi > Si > Ge > Sn > Pb > B > Al > Ga > In > Tl
//   (used when comparing heteroatoms of any kind, N now appears after Te)
static int p44_2_1_c_rank(int z) {
    switch (z) {
        case  9: return 0;  // F
        case 17: return 1;  // Cl
        case 35: return 2;  // Br
        case 53: return 3;  // I
        case  8: return 4;  // O
        case 16: return 5;  // S
        case 34: return 6;  // Se
        case 52: return 7;  // Te
        case 15: return 8;  // P
        case 33: return 9;  // As
        case 51: return 10; // Sb
        case 83: return 11; // Bi
        case 14: return 12; // Si
        case 32: return 13; // Ge
        case 50: return 14; // Sn
        case 82: return 15; // Pb
        case  5: return 16; // B
        case 13: return 17; // Al
        case 31: return 18; // Ga
        case 49: return 19; // In
        case 81: return 20; // Tl
        default: return 99; // unsupported / not in sequence
    }
}

static int p44_2_1_g_rank(int z) {
    switch (z) {
        case  9: return 0;  // F
        case 17: return 1;  // Cl
        case 35: return 2;  // Br
        case 53: return 3;  // I
        case  8: return 4;  // O
        case 16: return 5;  // S
        case 34: return 6;  // Se
        case 52: return 7;  // Te
        case  7: return 8;  // N
        case 15: return 9;  // P
        case 33: return 10; // As
        case 51: return 11; // Sb
        case 83: return 12; // Bi
        case 14: return 13; // Si
        case 32: return 14; // Ge
        case 50: return 15; // Sn
        case 82: return 16; // Pb
        case  5: return 17; // B
        case 13: return 18; // Al
        case 31: return 19; // Ga
        case 49: return 20; // In
        case 81: return 21; // Tl
        default: return 99; // unsupported / not in sequence
    }
}

// P-44.2.1 / P-44.4.1 / FR-2.3 tie-break: reconstructs cyclic traversal order for a simple
// monocyclic ring and computes its canonical (lowest) heteroatom locant set under all
// 2 * ringSize candidate numberings.
static std::vector<int> getCanonicalHeteroatomLocants(const Graph &g, const std::set<int> &ringNodes) {
    int ringSize = static_cast<int>(ringNodes.size());
    if (ringSize < 3) return {};

    // Validate simple monocycle: every ring atom must have exactly 2 ring-internal neighbors
    for (int n : ringNodes) {
        int deg = 0;
        for (int nei : g.nodes[n].neighbors) {
            if (ringNodes.count(nei)) deg++;
        }
        if (deg != 2) return {};
    }

    // Reconstruct cyclic traversal order
    std::vector<int> ringCycle;
    int startNode = *ringNodes.begin();
    int current = startNode;
    int previous = -1;
    for (int step = 0; step < ringSize; ++step) {
        ringCycle.push_back(current);
        int nextNode = -1;
        for (int nei : g.nodes[current].neighbors) {
            if (ringNodes.count(nei) && nei != previous) {
                nextNode = nei;
                break;
            }
        }
        if (nextNode == -1) return {};
        previous = current;
        current = nextNode;
    }
    if (static_cast<int>(ringCycle.size()) != ringSize) return {};
    if (current != startNode) return {};

    std::set<int> visited(ringCycle.begin(), ringCycle.end());
    if (static_cast<int>(visited.size()) != ringSize) return {};

    // Try all 2 * ringSize candidate numberings (rotations & directions)
    bool hasBest = false;
    std::vector<int> bestLocs;
    for (int st = 0; st < ringSize; ++st) {
        for (int dir = 0; dir < 2; ++dir) {
            std::vector<int> candLocs;
            for (int i = 0; i < ringSize; ++i) {
                int pos = (dir == 0) ? (st + i) % ringSize : (st - i + ringSize) % ringSize;
                int node = ringCycle[pos];
                if (g.nodes[node].atomicNumber != 6) {
                    candLocs.push_back(i + 1);
                }
            }
            if (!hasBest || candLocs < bestLocs) {
                bestLocs = candLocs;
                hasBest = true;
            }
        }
    }
    return bestLocs;
}

// P-44.2.1 tie-break comparison for two candidate rings.
// Returns: 1 if ring1 wins (is senior), -1 if ring2 wins, 0 if tied through all criteria.
// Both rings are assumed to be parent-eligible (pass isParentEligible) for this use case.
// Implements criteria (a) through (g) from Blue Book P-44.2.1 in order, stopping at first distinction.
static int compareRingSeniority(const Graph &g, const std::set<int> &ring1, const std::set<int> &ring2) {
    // Criterion (a): is a heterocycle
    bool r1_hasHetero = false, r2_hasHetero = false;
    for (int n : ring1) {
        if (g.nodes[n].atomicNumber != 6) { r1_hasHetero = true; break; }
    }
    for (int n : ring2) {
        if (g.nodes[n].atomicNumber != 6) { r2_hasHetero = true; break; }
    }
    // Since both rings passed isParentEligible, both must have at least one heteroatom
    // OR an exocyclic double/triple to O/N/S. But isParentEligible returns true for
    // exocyclic double/triple to O/N/S even on a carbocycle. However, for true rings
    // (SSSR rings), the exocyclic double bond check in isParentEligible is meant
    // for cases like cyclohexene (C=C exocyclic to the ring carbon). But in the
    // disjoint-ring context, we're dealing with the rings themselves.
    // For criterion (a), we need to check if the ring IS a heterocycle (has a
    // heteroatom in the ring itself).
    if (r1_hasHetero != r2_hasHetero) {
        return r1_hasHetero ? 1 : -1; // heterocycle > carbocycle
    }
    if (!r1_hasHetero && !r2_hasHetero) {
        // Both carbocycles - (a) doesn't distinguish
    }

    // Criterion (b): has at least one nitrogen atom
    bool r1_hasN = false, r2_hasN = false;
    for (int n : ring1) {
        if (g.nodes[n].atomicNumber == 7) { r1_hasN = true; break; }
    }
    for (int n : ring2) {
        if (g.nodes[n].atomicNumber == 7) { r2_hasN = true; break; }
    }
    if (r1_hasN != r2_hasN) {
        return r1_hasN ? 1 : -1; // has N > no N
    }

    // Criterion (c): has at least one heteroatom (in the absence of nitrogen)
    // that occurs earlier in the sequence F > Cl > Br > I > O > S > Se > Te > P > As > Sb > Bi > Si > Ge > Sn > Pb > B > Al > Ga > In > Tl
    // Only applies if both have the same nitrogen status (both have N or both don't)
    if (!r1_hasN && !r2_hasN) {
        // Find the earliest-ranked heteroatom in each ring
        int r1_earliest = 99, r2_earliest = 99;
        for (int n : ring1) {
            int z = g.nodes[n].atomicNumber;
            if (z != 6) {
                int rank = p44_2_1_c_rank(z);
                if (rank < r1_earliest) r1_earliest = rank;
            }
        }
        for (int n : ring2) {
            int z = g.nodes[n].atomicNumber;
            if (z != 6) {
                int rank = p44_2_1_c_rank(z);
                if (rank < r2_earliest) r2_earliest = rank;
            }
        }
        if (r1_earliest != r2_earliest) {
            return (r1_earliest < r2_earliest) ? 1 : -1;
        }
    }

    // Criterion (d): has the greater number of rings
    // In this code path, both rings are monocyclic SSSR rings, so both have exactly 1 ring
    // This will always be a tie for disjoint monocyclic rings
    // int r1_rings = 1, r2_rings = 1; // always equal for this use case

    // Criterion (e): has the greater number of skeletal atoms
    size_t r1_size = ring1.size();
    size_t r2_size = ring2.size();
    if (r1_size != r2_size) {
        return (r1_size > r2_size) ? 1 : -1;
    }

    // Criterion (f): has the greater number of heteroatoms of any kind
    int r1_numHetero = 0, r2_numHetero = 0;
    for (int n : ring1) {
        if (g.nodes[n].atomicNumber != 6) r1_numHetero++;
    }
    for (int n : ring2) {
        if (g.nodes[n].atomicNumber != 6) r2_numHetero++;
    }
    if (r1_numHetero != r2_numHetero) {
        return (r1_numHetero > r2_numHetero) ? 1 : -1;
    }

    // Criterion (g): has the greater number of heteroatoms occurring earlier in the sequence
    // F > Cl > Br > I > O > S > Se > Te > N > P > As > Sb > Bi > Si > Ge > Sn > Pb > B > Al > Ga > In > Tl
    // Count heteroatoms at each rank level for each ring, compare from most senior
    int r1_heteroAtRank[99] = {0}; // initialize to 0
    int r2_heteroAtRank[99] = {0};
    for (int n : ring1) {
        int z = g.nodes[n].atomicNumber;
        if (z != 6) {
            int rank = p44_2_1_g_rank(z);
            if (rank < 99) r1_heteroAtRank[rank]++;
        }
    }
    for (int n : ring2) {
        int z = g.nodes[n].atomicNumber;
        if (z != 6) {
            int rank = p44_2_1_g_rank(z);
            if (rank < 99) r2_heteroAtRank[rank]++;
        }
    }
    // Compare from rank 0 (most senior) upwards
    for (int rank = 0; rank < 99; rank++) {
        if (r1_heteroAtRank[rank] != r2_heteroAtRank[rank]) {
            return (r1_heteroAtRank[rank] > r2_heteroAtRank[rank]) ? 1 : -1;
        }
    }

    // Criterion (h): lowest locants for heteroatoms as a set (P-44.2.1 / P-44.4.1 / FR-2.3)
    // The ring whose heteroatoms occupy the lowest locant set (first point of difference,
    // ascending) is senior.
    std::vector<int> r1_locs = getCanonicalHeteroatomLocants(g, ring1);
    std::vector<int> r2_locs = getCanonicalHeteroatomLocants(g, ring2);
    if (!r1_locs.empty() && !r2_locs.empty()) {
        if (r1_locs < r2_locs) return 1;
        if (r2_locs < r1_locs) return -1;
    }

    // All criteria exhausted, still tied
    return 0;
}

// P-22.2.2.1.6: For 6-membered rings, find least-senior heteroatom present.
// Group A (O,S,Se,Te,Bi) and Group B (N,Si,Ge,Sn,Pb) -> mancude stem '-ine'.
// Group C (P,As,Sb,B) -> mancude stem '-inine'.

// Build a skeletal replacement prefix chunk (e.g. "2,4-dioxa-6-aza") for a set of heteroatoms.
// Reuses hwSeniorityRank/hwAPrefix and citation order from LARGE_HETEROCYCLE.
static QString buildSkeletalReplacementPrefix(const std::map<int, std::vector<int>> &locantsByZ, bool omitSingleLocant) {
    int totalHeteroCount = 0;
    for (const auto &kv : locantsByZ) totalHeteroCount += static_cast<int>(kv.second.size());
    if (totalHeteroCount == 0) return "";
    
    if (omitSingleLocant && totalHeteroCount == 1) {
        return hwAPrefix(locantsByZ.begin()->first);
    }
    
    static const int citationOrder[] = {8, 16, 34, 52, 7, 15, 33, 51, 83, 14, 32, 50, 82, 5};
    static const int citationOrderLen = 14;
    
    QStringList chunks;
    for (int k = 0; k < citationOrderLen; ++k) {
        int z = citationOrder[k];
        auto it = locantsByZ.find(z);
        if (it == locantsByZ.end()) continue;
        
        std::vector<int> locs = it->second;
        std::sort(locs.begin(), locs.end());
        QStringList locStrs;
        for (int l : locs) locStrs.append(QString::number(l));
        
        QString aPrefix = hwAPrefix(z);
        QString prefixWord;
        if (locs.size() == 1) {
            prefixWord = aPrefix;
        } else {
            QString mp = multiPrefix(static_cast<int>(locs.size()));
            if (mp.endsWith('a') && isVowel(aPrefix[0])) mp.chop(1);
            prefixWord = mp + aPrefix;
        }
        chunks.append(locStrs.join(",") + "-" + prefixWord);
    }
    return chunks.join("-");
}

static QString hwSixMemberStem(const std::vector<int> &heteroAtomicNumbers) {
    // Find the element with the highest (least-senior) rank
    int leastSeniorRank = -1;
    int leastSeniorZ = -1;
    for (int z : heteroAtomicNumbers) {
        int r = hwSeniorityRank(z);
        if (r > leastSeniorRank) {
            leastSeniorRank = r;
            leastSeniorZ = z;
        }
    }
    // Group C elements: P(15), As(33), Sb(51), B(5)
    if (leastSeniorZ == 15 || leastSeniorZ == 33 || leastSeniorZ == 51 || leastSeniorZ == 5) {
        return "inine";
    }
    // Group A: O,S,Se,Te,Bi; Group B: N,Si,Ge,Sn,Pb -- both use '-ine'
    return "ine";
}

// P-22.2.2.1.5.1 / Table 2.5: General Hantzsch-Widman stem selection for ring sizes 3-10.
// Returns the mancude (unsaturated) or saturated stem for the given ring size and
// heteroatom composition, per the caller's own `saturated` flag. Verified against
// Blue Book Table 2.5 and specific PIN examples:
//   size 3: unsaturated "irine" (all-N) / "irene" (otherwise); saturated "iridine"
//           (any N present, e.g. aziridine/oxaziridine) / "irane" (no N, e.g.
//           oxirane/thiirane)
//   size 4: unsaturated "ete" (always); saturated "etidine" (any N present, e.g.
//           azetidine) / "etane" (no N, e.g. oxetane/thietane)
//   size 5: unsaturated "ole" (always); saturated "olidine" (any N present, e.g.
//           pyrrolidine/oxazolidine) / "olane" (no N, e.g. dioxolane/dithiolane)
//   size 6: delegates to hwSixMemberStem (ine/inine by least-senior element) for
//           the unsaturated form; the saturated form is left to this file's own
//           retained-name RingTypes (piperidine, piperazine, morpholine, dioxane,
//           ...) rather than a systematic fallback here, since the exact
//           systematic saturated 6-ring suffix spelling for an UNretained
//           combination is not yet confirmed against a PIN example.
//   size 7: "epine" / saturated "epane" (azepine/azepane)
//   size 8: "ocine" / saturated "ocane" (diazocine/azocane)
//   size 9: "onine" / saturated "onane" (dioxonine/azonane)
//   size 10: "ecine" / saturated "ecane" (diazecine/azecane)
// For any other size, returns empty string (caller must guard against this).
static QString hwGeneralRingStem(int ringSize, const std::vector<int> &heteroAtomicNumbers, bool saturated = false) {
    bool anyN = false;
    for (int z : heteroAtomicNumbers) {
        if (z == 7) { anyN = true; break; }
    }
    switch (ringSize) {
        case 3: {
            if (saturated) return anyN ? "iridine" : "irane";
            // P-22.2.2.1.5.1: stem 'irine' is used in place of 'irene' for rings ONLY containing
            // nitrogen heteroatoms. Mixed composition (e.g. O+N) still uses '-irene'.
            if (heteroAtomicNumbers.empty()) return "irene"; // safety: no heteroatoms -> default
            for (int z : heteroAtomicNumbers) {
                if (z != 7) return "irene"; // 7 = nitrogen
            }
            return "irine";
        }
        case 4: return saturated ? (anyN ? "etidine" : "etane") : "ete";   // Confirmed by PINs: oxete, azete, azetidine, oxetane
        case 5: return saturated ? (anyN ? "olidine" : "olane") : "ole";   // 5-ring always "ole" unsaturated
        case 6: return hwSixMemberStem(heteroAtomicNumbers); // delegate to existing logic (see note above re: saturated)
        case 7: return saturated ? "epane" : "epine"; // Confirmed by PINs: azepine, azepane
        case 8: return saturated ? "ocane" : "ocine"; // Confirmed by PIN: diazocine, azocane
        case 9: return saturated ? "onane" : "onine"; // Confirmed by PIN: dioxonine, azonane
        case 10: return saturated ? "ecane" : "ecine"; // Confirmed by PIN: diazecine, azecane
        default: return ""; // should never happen for sizes accepted by tryGeneralHeterocycle
    }
}

// Builds the bare Hantzsch-Widman name (e.g. "1,2,4-triazole") for a
// GENERAL_HETEROCYCLE ring given one specific atom ordering (cand, a
// ring-size-length array of graph node indices -- the chosen candidate's
// own rotation/direction). Mirrors the bare-ring builder's own logic
// exactly (same citOrd citation order, same multiplying-prefix elision
// rules, same hwGeneralRingStem call) so both call sites produce
// identical names for the same ring, just reusable at any call site
// that already has its own candidate ordering (e.g. the N-ring chain
// fusion mechanism, which generates its own candidates independently of
// the bare-ring path). Does not add an indicated-hydrogen prefix --
// callers that need one handle it separately, matching every other
// RingType's own getBaseNameShared/getFusionPrefixShared contract.
static QString buildGeneralHeterocycleName(const Graph &g, const std::vector<int> &cand, int ringSize, bool saturated = false) {
    static const int citOrd[] = {8, 16, 34, 52, 7, 15, 33, 51, 83, 14, 32, 50, 82, 5};
    static const int citOrdLen = 14;
    std::map<int, std::vector<int>> locsByZ;
    std::vector<int> allZ;
    for (int ii = 0; ii < ringSize; ++ii) {
        int zz = g.nodes[cand[ii]].atomicNumber;
        if (zz != 6) { locsByZ[zz].push_back(ii + 1); allZ.push_back(zz); }
    }
    std::vector<int> allLs;
    for (int k = 0; k < citOrdLen; ++k) {
        auto it2 = locsByZ.find(citOrd[k]);
        if (it2 != locsByZ.end()) for (int l : it2->second) allLs.push_back(l);
    }
    QStringList lStrs;
    for (int l : allLs) lStrs.append(QString::number(l));
    QString locPfx = lStrs.join(",") + "-";
    QString ePfxs;
    for (int k = 0; k < citOrdLen; ++k) {
        int zz = citOrd[k];
        auto it2 = locsByZ.find(zz);
        if (it2 == locsByZ.end()) continue;
        int cnt = static_cast<int>(it2->second.size());
        QString ap = hwAPrefix(zz);
        QString mp = multiPrefix(cnt);
        if (mp.endsWith('a') && isVowel(ap[0])) mp.chop(1);
        QString chunk = mp + ap;
        if (!ePfxs.isEmpty() && ePfxs.endsWith('a') && chunk.startsWith('a')) ePfxs.chop(1);
        ePfxs += chunk;
    }
    QString st = hwGeneralRingStem(ringSize, allZ, saturated);
    if (st.isEmpty()) return QString();
    if (ePfxs.endsWith('a') && isVowel(st[0])) ePfxs.chop(1);
    return locPfx + ePfxs + st;
}

// P-25.3.1.3: the fusion prefix for an attached component is formed by
// replacing the component name's final letter 'e' by 'o' (indeno from
// indene), or by adding 'o' when no final 'e' is present (pyrano from
// pyran). Every Hantzsch-Widman stem this file produces ends in 'e'
// (Table 2.5: -irene/-irine, -ete, -ole, -ine/-inine, -epine, -ocine,
// -onine, -ecine), so the first branch is the one that fires in
// practice; the second branch is kept for correctness per the rule's
// own text, not because a real case here is expected to need it.
static QString toFusionPrefix(const QString &name) {
    if (name.isEmpty()) return name;
    if (name.endsWith('e')) return name.left(name.length() - 1) + "o";
    return name + "o";
}

// When a GENERAL_HETEROCYCLE ring is cited as an ATTACHED component (a
// fusion prefix before another ring's name), its own embedded heteroatom
// locants must be in square brackets -- real Blue Book PINs confirm this
// repeatedly for both prefix and base components with internal locants,
// e.g. "pyrido[2,3-d][1,2]oxazine", "imidazo[2,1-b][1,3]thiazole"
// (BlueBookV2.md:8213/8257). toFusionPrefix() alone (used when this ring
// is the unmodified BASE/root component, e.g. Task 1's own "2,1,3-
// benzoxadiazole" -- correct unbracketed per BlueBookV2.md:7847) doesn't
// add these brackets; this wraps the leading locant run from
// buildGeneralHeterocycleName/buildCanonicalGeneralHeterocycleName's own
// output before applying the same "e"->"o" transform to the stem.
static QString toFusionPrefixBracketed(const QString &name) {
    int i = 0;
    while (i < name.length() && (name[i].isDigit() || name[i] == ',')) i++;
    if (i > 0 && i < name.length() && name[i] == '-') {
        QString locants = name.left(i);
        QString rest = name.mid(i + 1);
        return "[" + locants + "]" + toFusionPrefix(rest);
    }
    return toFusionPrefix(name);
}

// I5 fix (final whole-branch review): P-22.2.2.1.1 forbids Hantzsch-Widman
// names for a monocyclic 6-ring whose sole heteroatom is O/S/Se/Te/Bi --
// "oxine"/"thiine"/etc are not real names; the mandatory retained names
// (pyran, thiopyran, etc) apply instead and are not implemented by the
// GENERAL_HETEROCYCLE mechanisms. Originally written inline only in the
// Phase 31 benzo-fusion mechanism; extracted here so the chain and
// branching mechanisms can reject the same case instead of producing a
// forbidden "...oxino.../...thiino..." name. Applies only to the single-
// heteroatom, 6-membered case -- a second heteroatom or a different ring
// size is unaffected (those already get a real Hantzsch-Widman name).
static bool isOxineAzineExcluded(const Graph &g, const std::vector<int> &hNodes, int ringSize) {
    if (ringSize != 6 || hNodes.size() != 1) return false;
    int z = g.nodes[hNodes[0]].atomicNumber;
    return z == 8 || z == 16 || z == 34 || z == 52 || z == 83;
}

// Builds a GENERAL_HETEROCYCLE ring's own canonical HW name directly from
// its real ring cycle (any fixed order -- e.g. straight from
// classifyMonocyclicHeteroRing's own buildCycle, not a pre-chosen
// candidate), self-contained rather than depending on an outer
// combinatorial search to have already picked the right rotation. Finds
// every rotation seeded from a most-senior heteroatom position (per
// P-22.2.2.1.3, locant 1 must go to one), keeps only the one(s) achieving
// the lexicographically lowest heteroatom-locant set, and builds the name
// from that. Used by mechanisms (like the branching one) that number each
// ring independently rather than running the chain mechanism's own
// multi-ring rotation search.
static QString buildCanonicalGeneralHeterocycleName(const Graph &g, const std::vector<int> &ringCycle, const std::vector<int> &hNodes) {
    int ringSize = static_cast<int>(ringCycle.size());
    int minRank = 99;
    for (int n : hNodes) {
        int r = hwSeniorityRank(g.nodes[n].atomicNumber);
        if (r < minRank) minRank = r;
    }
    std::vector<int> bestCand;
    std::vector<int> bestSet;
    for (int st = 0; st < ringSize; ++st) {
        if (hwSeniorityRank(g.nodes[ringCycle[st]].atomicNumber) != minRank) continue;
        for (int dir = 0; dir < 2; ++dir) {
            std::vector<int> cand(ringSize);
            std::vector<int> locs;
            for (int i = 0; i < ringSize; ++i) {
                int pos = dir == 0 ? (st + i) % ringSize : (st - i + ringSize) % ringSize;
                cand[i] = ringCycle[pos];
                if (g.nodes[cand[i]].atomicNumber != 6) locs.push_back(i + 1);
            }
            if (bestCand.empty() || locs < bestSet) { bestSet = locs; bestCand = cand; }
        }
    }
    if (bestCand.empty()) return QString();
    return buildGeneralHeterocycleName(g, bestCand, ringSize);
}

// P-14.7.1: Helper to find indicated hydrogen position in a monocyclic general heterocycle.
// Returns a sorted vector of all 1-based locants of saturated positions (where both ring bonds are single
// and the atom carries at least one H) in the given ring chain.
// Only checks ring-internal bonds (bonds to the two adjacent ring atoms).
// Note: After indigoAromatize(), bonds in aromatic systems have order 4 (not alternating 1/2).
// However, for odd-membered rings that cannot be fully aromatic (e.g., 7-membered with 4N),
// the bonds are still explicit single/double (not all order 4).
static std::vector<int> findIndicatedHydrogenLocants(const Graph &g, const std::vector<int> &ringChain) {
    int ringSize = static_cast<int>(ringChain.size());
    std::vector<int> indicatedHLocants;
    if (ringSize < 3) return indicatedHLocants; // not a valid ring

    // First pass: collect all positions with explicit single bonds to both neighbors
    for (int i = 0; i < ringSize; ++i) {
        int nodeIdx = ringChain[i];
        const GraphNode &node = g.nodes[nodeIdx];

        // Find the two ring neighbors in the chain
        int prevIdx = ringChain[(i - 1 + ringSize) % ringSize];
        int nextIdx = ringChain[(i + 1) % ringSize];

        // Find bond orders to prev and next in the ring
        int orderToPrev = -1;
        int orderToNext = -1;

        for (size_t j = 0; j < node.neighbors.size(); ++j) {
            if (node.neighbors[j] == prevIdx) {
                orderToPrev = node.bondOrders[j];
            } else if (node.neighbors[j] == nextIdx) {
                orderToNext = node.bondOrders[j];
            }
        }

        // An atom has an indicated hydrogen position if:
        // - Both ring bonds are NOT double or aromatic (i.e., both are single, order 1)
        //   This means the atom is sp3-hybridized in the ring (saturated).
        // - The atom carries at least one hydrogen (totalH >= 1)
        // Note: In a Kekulized structure (after aromatization), aromatic bonds are order 4,
        // and explicit single/double bonds are orders 1/2. An atom with two single bonds
        // to its ring neighbors is the saturated position.
        
        if (orderToPrev == 1 && orderToNext == 1 && node.totalH >= 1) {
            indicatedHLocants.push_back(i + 1); // 1-based locant
        }
    }

    // If no indicated hydrogen found via bond order check, but ring is odd-membered,
    // check if all bonds are aromatic (order 4). This can happen when Indigo treats
    // an odd-membered ring as aromatic even though it cannot be by Huckel's rule.
    // In such cases, structurally there MUST be one saturated position.
    if (indicatedHLocants.empty() && (ringSize == 3 || ringSize == 7 || ringSize == 9)) {
        bool allBondsAromatic = true;
        std::vector<int> hAtoms;
        
        for (int i = 0; i < ringSize; ++i) {
            int nodeIdx = ringChain[i];
            const GraphNode &node = g.nodes[nodeIdx];

            int prevIdx = ringChain[(i - 1 + ringSize) % ringSize];
            int nextIdx = ringChain[(i + 1) % ringSize];

            int orderToPrev = -1;
            int orderToNext = -1;

            for (size_t j = 0; j < node.neighbors.size(); ++j) {
                if (node.neighbors[j] == prevIdx) {
                    orderToPrev = node.bondOrders[j];
                } else if (node.neighbors[j] == nextIdx) {
                    orderToNext = node.bondOrders[j];
                }
            }

            if (orderToPrev != 4 || orderToNext != 4) {
                allBondsAromatic = false;
            }

            // Track atoms with totalH >= 1
            if (node.totalH >= 1) {
                hAtoms.push_back(i + 1); // 1-based locant
            }
        }

        // If all bonds are aromatic and this is an odd-membered ring,
        // there must be exactly one saturated position. Use the first atom
        // with totalH >= 1 as the indicated hydrogen position.
        // Note: For odd-membered rings, structural constraints guarantee
        // exactly one such position exists in the mancude form.
        if (allBondsAromatic && !hAtoms.empty()) {
            indicatedHLocants.push_back(hAtoms[0]);
        }
    }

    std::sort(indicatedHLocants.begin(), indicatedHLocants.end());
    return indicatedHLocants;
}

// Returns the 1-based locant of the saturated position (where both ring bonds are single
// and the atom carries at least one H), or -1 if no such position, or -2 if 2+ positions.
// Only checks ring-internal bonds (bonds to the two adjacent ring atoms).
// Note: After indigoAromatize(), bonds in aromatic systems have order 4 (not alternating 1/2).
// However, for odd-membered rings that cannot be fully aromatic (e.g., 7-membered with 4N),
// the bonds are still explicit single/double (not all order 4).
static int findIndicatedHydrogenLocant(const Graph &g, const std::vector<int> &ringChain) {
    std::vector<int> locants = findIndicatedHydrogenLocants(g, ringChain);
    if (locants.empty()) return -1;
    if (locants.size() == 1) return locants[0];
    return -2; // 2+ positions
}

// A single-heteroatom mancude ring (furan, pyridine, oxepine, ...) needs no
// indicated-hydrogen citation when the heteroatom itself -- not a carbon --
// occupies the ring's one position with two single bonds (it has no H to
// cite there regardless). findIndicatedHydrogenLocant requires totalH >= 1
// at that position, so it correctly returns -1 for this case, but -1 also
// covers a genuinely over-conjugated ring with no such position at all;
// this check distinguishes the two by looking at the heteroatom's own ring
// bonds directly, independent of its H count.
static bool heteroatomAtSaturatedPosition(const Graph &g, const std::vector<int> &ringChain, int heteroNode) {
    int ringSize = static_cast<int>(ringChain.size());
    int pos = -1;
    for (int i = 0; i < ringSize; ++i) if (ringChain[i] == heteroNode) { pos = i; break; }
    if (pos == -1) return false;
    int prevIdx = ringChain[(pos - 1 + ringSize) % ringSize];
    int nextIdx = ringChain[(pos + 1) % ringSize];
    const GraphNode &node = g.nodes[heteroNode];
    int orderToPrev = -1, orderToNext = -1;
    for (size_t j = 0; j < node.neighbors.size(); ++j) {
        if (node.neighbors[j] == prevIdx) orderToPrev = node.bondOrders[j];
        else if (node.neighbors[j] == nextIdx) orderToNext = node.bondOrders[j];
    }
    return orderToPrev == 1 && orderToNext == 1;
}

// P-22.2.2.1: tryGeneralHeterocycle -- gates entry into GENERAL_HETEROCYCLE path.
// Validates all ring heteroatoms are in the P-22.2.2.1.3 supported set.
// Actual name is assembled downstream in the GENERAL_HETEROCYCLE branch at ~line 7251.
// Returns false (triggering rejection) for any unsupported element or ring size.
bool tryGeneralHeterocycle(const Graph &g, const std::vector<int> &ringHeteroNodes, int ringSize, QString &outNameFragment) {
    // P-22.2.2.1.1: Hantzsch-Widman applies to monocyclic rings of size 3-10.
    // P-22.2.4 covers rings of size 11+ (out of scope for this phase).
    if (ringSize < 3 || ringSize > 10) return false;
    for (int nIdx : ringHeteroNodes) {
        int z = g.nodes[nIdx].atomicNumber;
        if (hwSeniorityRank(z) == 99) return false; // unsupported element
    }
    // Return true with a non-empty placeholder; downstream code builds the real name.
    outNameFragment = "<GENERAL_HETEROCYCLE>";
    return true;
}

enum class RingType { BENZENE, FURAN, THIOPHENE, SELENOPHENE, TELLUROPHENE, PYRROLE, PYRIDINE, PHOSPHININE, CYCLOALKANE, CYCLOALKENE, IMIDAZOLE, PYRIMIDINE, PYRAZOLE, OXAZOLE, ISOXAZOLE, THIAZOLE, ISOTHIAZOLE, SELENAZOLE, ISOSELENAZOLE, PYRIDAZINE, PYRAZINE, PIPERIDINE, PYRROLIDINE, PIPERAZINE, MORPHOLINE, THIOMORPHOLINE, IMIDAZOLIDINE, OXAZOLIDINE, ISOXAZOLIDINE, THIAZOLIDINE, ISOTHIAZOLIDINE, PYRAZOLIDINE, DIOXOLANE, DITHIOLANE, DIOXANE, DITHIANE, TETRAHYDROFURAN, TETRAHYDROTHIOPHENE, CYCLOPENTADIENE, CYCLOHEPTATRIENE, AZEPINE, OXEPINE, THIEPINE, SELENEPINE, TELLUREPINE, GENERAL_HETEROCYCLE, LARGE_HETEROCYCLE };

